function validate([n, primes]) {
  if (!Number.isInteger(n) || n < 1 || n > 100000) return 'n is between 1 and 100000.';
  if (primes.length < 1 || primes.length > 100) return 'primes needs 1 to 100 values.';
  for (let i = 0; i < primes.length; i++) {
    const p = primes[i];
    if (p < 2 || p > 1000) return 'Each prime is between 2 and 1000.';
    for (let d = 2; d * d <= p; d++) if (p % d === 0) return `${p} is not a prime.`;
    if (i > 0 && primes[i - 1] >= p) return 'primes must be strictly increasing.';
  }
  // Count super ugly numbers up to 2^31 - 1, stopping at n, to confirm the answer fits.
  const LIMIT = 2147483647;
  let count = 1;
  const visit = (value, from) => {
    for (let i = from; i < primes.length && count < n; i++) {
      const next = value * primes[i];
      if (next > LIMIT) break;
      count++;
      visit(next, i);
    }
  };
  visit(1, 0);
  if (count < n) return 'The n-th super ugly number must fit in a 32-bit signed integer.';
  return null;
}

