function nthSuperUglyNumber(n, primes) {
  const ugly = new Array(n);
  ugly[0] = 1;
  const index = new Array(primes.length).fill(0);
  const candidate = primes.slice();

  for (let i = 1; i < n; i++) {
    let next = Infinity;
    for (let j = 0; j < primes.length; j++) {
      next = Math.min(next, candidate[j]);
    }
    ugly[i] = next;
    for (let j = 0; j < primes.length; j++) {
      if (candidate[j] === next) {
        index[j]++;
        candidate[j] = ugly[index[j]] * primes[j];
      }
    }
  }
  return ugly[n - 1];
}

