function nthSuperUglyNumber(n, primes) {
  // List every super ugly number up to a bound, doubling the bound until there are at least n.
  let bound = 1;
  for (;;) {
    const found = [];
    const collect = (value, from) => {
      found.push(value);
      for (let i = from; i < primes.length && value * primes[i] <= bound; i++) collect(value * primes[i], i);
    };
    collect(1, 0);
    if (found.length >= n) return found.sort((a, b) => a - b)[n - 1];
    bound *= 2;
  }
}

