function generate(rand, size) {
  const LIMIT = 2147483647;
  const pool = [];
  for (let v = 2; v <= 1000; v++) {
    let prime = true;
    for (let d = 2; d * d <= v; d++) if (v % d === 0) { prime = false; break; }
    if (prime) pool.push(v);
  }
  // How many super ugly numbers are <= LIMIT, stopping once `cap` are found.
  const countUpTo = (primes, cap) => {
    let count = 1;
    const visit = (value, from) => {
      for (let i = from; i < primes.length && count < cap; i++) {
        const next = value * primes[i];
        if (next > LIMIT) break;
        count++;
        visit(next, i);
      }
    };
    visit(1, 0);
    return count;
  };
  for (;;) {
    let primes, n;
    if (size === 'large') {
      const k = 40 + Math.floor(rand() * 61);
      const chosen = new Set([2, 3, 5]);
      while (chosen.size < k) chosen.add(pool[Math.floor(rand() * pool.length)]);
      primes = [...chosen].sort((a, b) => a - b);
      n = 20000 + Math.floor(rand() * 20001);
    } else {
      const k = 1 + Math.floor(rand() * 6);
      const span = rand() < 0.8 ? 15 : pool.length;
      const chosen = new Set();
      while (chosen.size < k) chosen.add(pool[Math.floor(rand() * span)]);
      primes = [...chosen].sort((a, b) => a - b);
      n = 1 + Math.floor(rand() * 40);
    }
    if (countUpTo(primes, n) >= n) return [n, primes];
  }
}
